// 운명의 균열 (Rift of Fate) — 게임 데이터 (화면·서버 공용, 두 곳 파일이 똑같아야 함: test-rift가 검사)
// 카드·유물·적·이벤트·공명·각인은 모두 데이터. 효과는 ops 목록 → rift-core.js 효과 엔진이 실행
// 이름은 [한국어, 日本語, English]. 카드 설명은 ops에서 자동으로 만들어 실제 효과와 항상 같음
// 그림: spr = [시트, 열, 행] (cr = Tiny Creatures, td = Tiny Dungeon, 16px, CC0) · ic = [열, 행] (Kenney 1-Bit Pack, CC0)
// =========================
const O = {
  dmg: (n, o = {}) => ({ op: "DAMAGE", n, ...o }), blk: (n, o = {}) => ({ op: "BLOCK", n, ...o }), heal: (n, o = {}) => ({ op: "HEAL", n, ...o }),
  draw: (n) => ({ op: "DRAW", n }), disc: (n) => ({ op: "DISCARD", n }), en: (n) => ({ op: "ENERGY", n }),
  ap: (s, n, o = {}) => ({ op: "APPLY", s, n, ...o }), me: (s, n) => ({ op: "APPLY", s, n, tgt: "self" }),
  rep: (times, ops) => ({ op: "REPEAT", times, ops }), iff: (cond, then, els) => ({ op: "IF", cond, then, else: els || [] }),
  delay: (ops, turns = 1) => ({ op: "DELAY", ops, turns }), pow: (id, n = 1) => ({ op: "POWER", id, n }),
  sand: (n) => ({ op: "GAIN", res: "sand", n }), selfdmg: (n) => ({ op: "SELF_DAMAGE", n }),
  addc: (id, n = 1) => ({ op: "ADD_CARD", id, n }), sm: (k, v, n = 1) => ({ op: "SUMMON", k, v, n }), luck: (n) => ({ op: "GAIN", res: "luck", n }),
  chance: (p, then, els = []) => ({ op: "CHANCE", p, then, else: els }), roll: (d, n, then) => ({ op: "ROLL", d, n, then }),
};
const { dmg, blk, heal, draw, disc, en, ap, me, rep, iff, delay, pow, sand, selfdmg, addc, sm, luck, chance, roll } = O;

